const required = ['SHOPIFY_STORE_DOMAIN','SHOPIFY_API_VERSION','GOOGLE_SHEETS_WORKBOOK_ID','AI_PRIMARY_PROVIDER','AI_PRIMARY_MODEL'];
const safety = ['AUTO_PUBLISH_PRODUCTS','AUTO_SUBMIT_SUPPLIER_ORDERS','AUTO_SEND_SUPPORT_MESSAGES','AUTO_PROCESS_REFUNDS','AUTO_CREATE_DISCOUNTS','AUTO_LAUNCH_CAMPAIGNS'];
const missing = required.filter((key) => !$env[key] || String($env[key]).startsWith('replace-'));
const unsafe = safety.filter((key) => String($env[key]).toLowerCase() !== 'false');
const correlationId = $execution.id ? `health-${$execution.id}` : `health-${Date.now()}`;
return [{ json: { status: missing.length || unsafe.length ? 'BLOCKED' : 'READY', correlation_id: correlationId, checked_at: new Date().toISOString(), required_configuration: { total: required.length, missing }, safety_gates: { total: safety.length, unsafe }, secrets_checked: false, next_action: missing.length ? 'Configure missing values' : unsafe.length ? 'Restore safe launch defaults' : 'Run database and integration checks' } }];
